import{_ as a,o as s,c as n,a2 as e}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"案例 04 · VF 工艺薯条脆","description":"","frontmatter":{},"headers":[],"relativePath":"cases/case-04-vf-fries-crisp.md","filePath":"cases/case-04-vf-fries-crisp.md","lastUpdated":1787714366000}'),p={name:"cases/case-04-vf-fries-crisp.md"};function o(i,t,l,r,d,c){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="案例-04-·-vf-工艺薯条脆" tabindex="-1">案例 04 · VF 工艺薯条脆 <a class="header-anchor" href="#案例-04-·-vf-工艺薯条脆" aria-label="Permalink to &quot;案例 04 · VF 工艺薯条脆&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">这是教学演示案例</p><p>用于展示<strong>看不见的工艺怎么变成看得见的画面</strong>，以及技术卖点的合规边界。<strong>不是真实客户项目的复盘</strong>，数字为基于典型情况的合理估计。</p><p>文中涉及的工艺原理为通用食品工程常识，具体产品的工艺参数请以技术方提供的资料为准。</p></div><blockquote><p><strong>一句话</strong>：卖工艺的广告，最大的敌人不是画面不好看，是<strong>说错话</strong>。</p></blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>品类</td><td>预包装休闲零食 · VF 薯条脆</td></tr><tr><td>交付形态</td><td>20 秒竖屏 + 详情页配图 6 张</td></tr><tr><td>投放渠道</td><td>电商详情页 + 社媒种草</td></tr><tr><td>工期</td><td>4 天（其中 1 天用于核查与审校）</td></tr><tr><td>出片率</td><td>约 80 条生成 / 11 条采用</td></tr></tbody></table><hr><h2 id="_1-创意点" tabindex="-1">① 创意点 <a class="header-anchor" href="#_1-创意点" aria-label="Permalink to &quot;① 创意点&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>一款采用 VF 工艺（Vacuum Frying，真空低温油炸）的薯条脆，包装零食，走电商渠道。</p><p>客户的诉求很直接：<strong>「我们的工艺不一样，要把这个讲出来。」</strong></p><h3 id="先搞清楚-vf-到底是什么" tabindex="-1">先搞清楚 VF 到底是什么 <a class="header-anchor" href="#先搞清楚-vf-到底是什么" aria-label="Permalink to &quot;先搞清楚 VF 到底是什么&quot;">​</a></h3><p>做这类项目，<strong>第一件事不是想创意，是把技术搞懂</strong>。搞不懂就只能写空话，或者写错话。</p><p>VF 的基本原理（通用食品工程常识）：</p><table tabindex="0"><thead><tr><th>环节</th><th>发生了什么</th></tr></thead><tbody><tr><td>抽真空</td><td>罐内形成负压环境</td></tr><tr><td>沸点降低</td><td>负压下油和水的沸点都下降</td></tr><tr><td>低温脱水</td><td>因此可以在比常压油炸低得多的温度下完成脱水</td></tr><tr><td>形成多孔结构</td><td>水分快速汽化留下气孔，这是酥脆的来源</td></tr><tr><td>离心脱油</td><td>出料后甩掉表面附着的油</td></tr></tbody></table><p><strong>关键推论</strong>：低温意味着原料的色泽和风味物质受热破坏更少——所以 VF 产品往往能保留接近原料本身的颜色。</p><div class="danger custom-block"><p class="custom-block-title">这里有一个必须诚实面对的事实</p><p><strong>VF 是油炸，不是非油炸。</strong></p><p>它是&quot;真空低温油炸&quot;，工艺路径仍然是油炸，成品仍然含油。把 VF 宣传成「非油炸」是虚假宣传。</p><p>这一条要在项目一开始就跟客户对齐。有些客户会希望你往「非油炸」的方向靠——这时候要顶住。<strong>这不是创意问题，是法律问题。</strong></p></div><h3 id="限制条件-这个项目最重的部分" tabindex="-1">限制条件（这个项目最重的部分） <a class="header-anchor" href="#限制条件-这个项目最重的部分" aria-label="Permalink to &quot;限制条件（这个项目最重的部分）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>不能说</th><th>为什么</th></tr></thead><tbody><tr><td>非油炸</td><td>事实错误，VF 就是油炸</td></tr><tr><td>更健康 / 低脂 / 0 负担</td><td>营养声称（如「低脂」）在国标下有明确的量化门槛，须产品实测达标并按规范标示才能用。不是想说就能说</td></tr><tr><td>吃了不长胖 / 适合减肥</td><td>功效宣称，普通食品不得涉及</td></tr><tr><td>任何疾病相关表述</td><td>食品广告的绝对红线</td></tr><tr><td>「减少有害物质」类表述</td><td>即便有科学依据，在广告里说会被认定为暗示健康功效</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">关于最后一条</p><p>高温油炸淀粉类食品会产生一些高温副产物，低温工艺理论上有助于减少——这是真实的食品科学。</p><p>**但知道不等于能说。**在广告里提这件事，等于暗示「我们的更安全」，这属于健康功效暗示，风险很高，还容易被认定为贬低同类产品。</p><p>**放进知识储备，不放进文案。**这个分寸感是做工艺类广告的基本功。</p></div><h3 id="洞察" tabindex="-1">洞察 <a class="header-anchor" href="#洞察" aria-label="Permalink to &quot;洞察&quot;">​</a></h3><p>消费者对「油炸」有本能的抗拒，但又抵挡不住脆的东西。这个矛盾一直存在。</p><p>VF 的价值恰好落在这条缝里——但<strong>不能直接把这层价值说出来</strong>（说出来就是健康宣称）。</p><h3 id="big-idea" tabindex="-1">Big Idea <a class="header-anchor" href="#big-idea" aria-label="Permalink to &quot;Big Idea&quot;">​</a></h3><blockquote><p><strong>不说工艺的好处，只展示工艺的做法。</strong></p></blockquote><p>这是本案例最核心的判断。</p><p>「更健康」是<strong>结论</strong>——违规、且消费者不信。 「我们在负压环境下用低温炸了它」是<strong>事实</strong>——合规、可展示、且消费者会自己得出结论。</p><div class="tip custom-block"><p class="custom-block-title">这条能迁移到所有技术卖点类项目</p><p>冻干、冷压、慢烘、低温萃取……凡是「工艺不一样」的产品，都适用同一个策略：</p><p>**展示过程，让消费者自己下结论。**你替他下结论，既违规又不可信；他自己下的结论，他才信。</p></div><h3 id="淘汰掉的方向与理由" tabindex="-1">淘汰掉的方向与理由 <a class="header-anchor" href="#淘汰掉的方向与理由" aria-label="Permalink to &quot;淘汰掉的方向与理由&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方向</th><th>淘汰理由</th></tr></thead><tbody><tr><td>「0 负担的轻食零食」</td><td>功效暗示，合规风险高。且「0 负担」是典型的擦边表述，平台审核也未必过</td></tr><tr><td>「妈妈放心的选择」</td><td>用信任转移的方式暗示健康，绕了个弯还是同一个问题</td></tr><tr><td>「还原土豆本味」</td><td>方向没错，但太平淡，且「本味」几乎无法视觉化</td></tr><tr><td>「对比传统油炸」的对照结构</td><td>**风险最高的一个。**直接对比容易构成贬低同类产品，在广告法下有明确风险</td></tr></tbody></table><p><strong>最后一条值得展开</strong>：客户最初想要的就是对比结构（左边传统、右边 VF）。这个诉求要挡回去——不是因为效果不好，是因为它把一个创意问题变成了法务问题。</p><p>替代方案：只展示自己的工艺，不出现任何参照物。观众的对比是在他自己脑子里完成的。</p><hr><h2 id="_2-生成链路" tabindex="-1">② 生成链路 <a class="header-anchor" href="#_2-生成链路" aria-label="Permalink to &quot;② 生成链路&quot;">​</a></h2><h3 id="这个项目里-ai-承担的角色变了" tabindex="-1">这个项目里 AI 承担的角色变了 <a class="header-anchor" href="#这个项目里-ai-承担的角色变了" aria-label="Permalink to &quot;这个项目里 AI 承担的角色变了&quot;">​</a></h3><p>前三个案例里，AI 做的是「把能拍的东西拍出来」。这个项目不一样：</p><p><strong>核心画面全都是实拍不可能拍到的。</strong></p><table tabindex="0"><thead><tr><th>要展示的</th><th>实拍可行性</th></tr></thead><tbody><tr><td>真空罐内部的油炸过程</td><td>不可行——设备封闭、负压环境，没有观察窗</td></tr><tr><td>薯条脆断面的蜂窝气孔结构</td><td>需要电镜，成本极高且画面不美观</td></tr><tr><td>水分从组织中汽化逸出</td><td>微观尺度，拍不到</td></tr><tr><td>温度差异的视觉表达</td><td>抽象概念，无实物</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">AI 在广告里最被低估的价值</p><p>不是「拍得更好」，而是**「拍得到拍不到的东西」**。</p><p>案例 03 展示的是 AI 拍真实食物的弱点（容易塑料感）。这个案例正好相反——<strong>越是现实中不存在的画面，AI 的相对优势越大</strong>，因为没有真实参照物去比对，观众也无从挑剔。</p><p>技术类、工艺类、原理类的内容，是 AI 广告目前性价比最高的应用场景之一。</p></div><h3 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 技术理解 + 事实核查（人 + 技术方确认）  ← 本案例特有</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>② 工艺原理 → 视觉隐喻的转化（人）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>③ 概念视觉生成：拍不到的画面（图像模型）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>④ 质感镜头：断面、气孔（图像模型，微距）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>⑤ 包装实拍 + 合成（实拍 + 设计软件）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>⑥ 合规审校（人 / 法务）  ← 本案例特有</span></span></code></pre></div><p>第 ① 步和第 ⑥ 步是前三个案例没有的。<strong>卖感官的广告不需要它们，卖技术主张的广告必须有。</strong></p><h3 id="工艺原理-→-视觉隐喻" tabindex="-1">工艺原理 → 视觉隐喻 <a class="header-anchor" href="#工艺原理-→-视觉隐喻" aria-label="Permalink to &quot;工艺原理 → 视觉隐喻&quot;">​</a></h3><p>这一步是创意的实际发生处。把技术语言翻译成画面语言：</p><table tabindex="0"><thead><tr><th>技术事实</th><th>视觉隐喻</th><th>落到哪个镜头</th></tr></thead><tbody><tr><td>负压环境</td><td>悬浮、静止、无重力感的空间</td><td>镜头 2</td></tr><tr><td>低温</td><td>冷色调、缓慢、无剧烈翻腾</td><td>镜头 3</td></tr><tr><td>水分汽化</td><td>细密气泡从内部缓慢逸出</td><td>镜头 3</td></tr><tr><td>多孔结构</td><td>蜂窝状断面，光从孔隙穿过</td><td>镜头 5</td></tr><tr><td>保留原色</td><td>高饱和的自然黄色</td><td>全片</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">隐喻要基于事实，不能为了好看编造</p><p>「负压 → 悬浮感」是合理的视觉转化，因为它传达的是&quot;环境不同&quot;这个真实信息。</p><p>但如果画一个&quot;分子被温柔地包裹起来&quot;之类的画面，就是在编造一个不存在的机制——这叫伪科学包装，既不诚实，也经不起懂行的人推敲。</p><p>**判断标准：这个画面对应的技术事实，能不能在技术资料里找到出处？**找不到就别画。</p></div><h3 id="分镜表-20-秒-7-镜" tabindex="-1">分镜表（20 秒，7 镜） <a class="header-anchor" href="#分镜表-20-秒-7-镜" aria-label="Permalink to &quot;分镜表（20 秒，7 镜）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>时长</th><th>景别</th><th>主体与动作</th><th>光</th><th>备注</th></tr></thead><tbody><tr><td>1</td><td>0–3s</td><td>特写</td><td>新鲜土豆切片落在金属台面</td><td>侧逆光</td><td>交代原料</td></tr><tr><td>2</td><td>3–6s</td><td>中景</td><td>切片悬浮在暗色空间中，静止无重力</td><td>冷调轮廓光</td><td><strong>负压的隐喻</strong></td></tr><tr><td>3</td><td>6–10s</td><td>微距</td><td>细密气泡从切片内部缓慢逸出</td><td>逆光，气泡被点亮</td><td><strong>核心镜头</strong></td></tr><tr><td>4</td><td>10–12s</td><td>特写</td><td>色泽从生土豆的浅白转为金黄</td><td>转暖色</td><td>保留原色</td></tr><tr><td>5</td><td>12–15s</td><td>微距</td><td>掰断，断面蜂窝气孔清晰，光从孔隙穿过</td><td>强逆光</td><td><strong>酥脆的证据</strong></td></tr><tr><td>6</td><td>15–18s</td><td>特写</td><td>成品堆叠，自然掉落</td><td>暖侧逆光</td><td>食欲感</td></tr><tr><td>7</td><td>18–20s</td><td>中景</td><td>包装袋，字幕出</td><td>柔和产品光</td><td>实拍合成</td></tr></tbody></table><p><strong>结构逻辑</strong>：原料 → 工艺 → 结果 → 产品。这是工艺类广告的标准骨架，比讲故事更适合详情页场景。</p><div class="tip custom-block"><p class="custom-block-title">要直接用 Gemini 出片？</p><p>这七个镜头的<strong>可直接粘贴的 Gemini 提示词</strong>（含 negative prompt 与音频描述）在本页的 <a href="#附-·-用-gemini-直接生成视频的完整提示词">附录小节</a>，同时标注了哪三条纯文生视频做不出来、该走什么替代方案。</p></div><h3 id="数字" tabindex="-1">数字 <a class="header-anchor" href="#数字" aria-label="Permalink to &quot;数字&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>总生成 / 采用</td><td>约 80 条 / 11 条（视频 5 条 + 静图 6 张）</td></tr><tr><td>技术理解与核查</td><td>约 1 天</td></tr><tr><td>概念视觉</td><td>约 1 天</td></tr><tr><td>质感与合成</td><td>约 1 天</td></tr><tr><td>合规审校与改稿</td><td>约 1 天</td></tr><tr><td>返工点</td><td><strong>镜头 5（蜂窝断面）</strong>——气孔结构的合理性反复调；<strong>文案三轮返工</strong>——每轮都是合规问题</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">注意这个工期结构</p><p>四天里有<strong>整整一天</strong>花在核查和审校上，不产出任何画面。</p><p>这是工艺类项目和感官类项目最大的成本差异。报价时必须把它算进去——否则你会发现自己在免费做法务工作。</p></div><hr><h2 id="_3-关键-prompt" tabindex="-1">③ 关键 Prompt <a class="header-anchor" href="#_3-关键-prompt" aria-label="Permalink to &quot;③ 关键 Prompt&quot;">​</a></h2><h3 id="prompt-1-·-镜头-2-真空环境-拍不到的画面" tabindex="-1">Prompt 1 · 镜头 2 真空环境（拍不到的画面） <a class="header-anchor" href="#prompt-1-·-镜头-2-真空环境-拍不到的画面" aria-label="Permalink to &quot;Prompt 1 · 镜头 2 真空环境（拍不到的画面）&quot;">​</a></h3><p><strong>适用场景</strong> 把抽象的物理环境转化为可感知的画面。 <strong>不适用</strong>：需要写实还原真实设备的场合——这是隐喻，不是纪实。</p><p><strong>可复制 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一片薄薄的生土豆切片静止悬浮在深色的虚空中，周围没有任何支撑物，</span></span>
<span class="line"><span>切片边缘极其清晰，环境中有极细微的悬浮颗粒同样静止不动，</span></span>
<span class="line"><span></span></span>
<span class="line"><span>概念科学可视化，暗调，冷色调偏青蓝，极简，</span></span>
<span class="line"><span>100mm 微距镜头，极浅景深 f/2.8，平视机位，</span></span>
<span class="line"><span>单一冷白色轮廓光从右后方勾勒切片边缘，背景为纯粹的深黑，</span></span>
<span class="line"><span>竖版 9:16，高细节，画面干净</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向：文字、水印、油、液体、翻腾、气泡、多个物体、杂乱背景</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>关键词</th><th>在控制什么</th><th>想改效果时</th></tr></thead><tbody><tr><td>静止悬浮 + 没有支撑物</td><td>**负压的核心视觉表达。**悬浮传达&quot;环境不寻常&quot;</td><td>想更强烈可加&quot;时间凝固&quot;</td></tr><tr><td>悬浮颗粒同样静止</td><td>强化&quot;整个空间都静止&quot;，比只有主体悬浮更有说服力</td><td>——</td></tr><tr><td>冷色调偏青蓝</td><td>低温的色彩编码，和镜头 4 的转暖形成呼应</td><td>——</td></tr><tr><td>翻腾、气泡（负向）</td><td>**这一镜要的是&quot;静&quot;。**有气泡就变成了常规油炸的画面，隐喻失效</td><td>——</td></tr></tbody></table><p><strong>常见翻车点</strong></p><ul><li><strong>画成了真实的油锅</strong>。模型看到&quot;土豆&quot;「炸」会默认给你翻滚的油锅——那正是要避开的画面。所以 Prompt 里完全不提油和炸，只描述悬浮状态。</li><li><strong>加了太多科技元素</strong>。数据流、光效、粒子特效——一加就变成劣质科技广告。<strong>极简是这一镜的关键。</strong></li><li><strong>观众看不懂</strong>。这一镜单独看确实抽象，它依赖后面镜头的上下文，以及字幕的一句说明。<strong>概念镜头不能孤立存在。</strong></li></ul><hr><h3 id="prompt-2-·-镜头-5-蜂窝断面-酥脆的物证" tabindex="-1">Prompt 2 · 镜头 5 蜂窝断面（酥脆的物证） <a class="header-anchor" href="#prompt-2-·-镜头-5-蜂窝断面-酥脆的物证" aria-label="Permalink to &quot;Prompt 2 · 镜头 5 蜂窝断面（酥脆的物证）&quot;">​</a></h3><p><strong>适用场景</strong> 用微观结构为「酥脆」提供视觉证据。这是全片说服力最强的一镜。</p><p><strong>可复制 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一片薯条脆被掰成两半，断面正对镜头，</span></span>
<span class="line"><span>断面呈现不规则的蜂窝状多孔结构，孔隙大小不均，</span></span>
<span class="line"><span>强烈的逆光从断面背后穿过孔隙，形成明亮的透光点，</span></span>
<span class="line"><span></span></span>
<span class="line"><span>食品微距摄影，暖金色调，轻微胶片颗粒，</span></span>
<span class="line"><span>100mm 微距镜头，极浅景深，平视机位，</span></span>
<span class="line"><span>强逆光，光线穿透孔隙，边缘有明亮轮廓，背景压暗虚化，</span></span>
<span class="line"><span>竖版 9:16，超高细节，真实食物质感</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向：文字、水印、塑料感、规则的孔洞、蜂巢图案、完美对称、CGI 感</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>关键词</th><th>在控制什么</th><th>想改效果时</th></tr></thead><tbody><tr><td><strong>孔隙大小不均</strong></td><td>**本条最关键。**不写的话模型会画出规整的蜂巢图案，一看就假</td><td>想更真实加&quot;孔壁厚薄不一&quot;</td></tr><tr><td>光线穿透孔隙</td><td>透光是&quot;多孔&quot;最直观的证明，比单纯展示孔洞有力得多</td><td>想更戏剧化就加&quot;背景纯黑&quot;</td></tr><tr><td>规则的孔洞 / 蜂巢图案（负向）</td><td>模型对&quot;蜂窝&quot;的默认理解是六边形蜂巢——<strong>必须排除</strong></td><td>——</td></tr><tr><td>完美对称（负向）</td><td>同 <a href="/cases/case-03-fries-social">案例 03</a> 的结论：完美即虚假</td><td>——</td></tr></tbody></table><p><strong>常见翻车点</strong></p><ul><li><strong>画成了标准蜂巢</strong>。「蜂窝状」这个词会触发六边形规则结构，那是蜜蜂做的，不是油炸做的。<strong>必须显式排除，并强调&quot;不规则&quot;&quot;大小不均&quot;。</strong></li><li><strong>孔隙结构不符合物理</strong>。孔太大、壁太薄，看起来像泡沫塑料。多生成几版，挑结构合理的。</li><li><strong>过度美化</strong>。这一镜的说服力来自&quot;真实&quot;，修得太漂亮反而失效。</li></ul><hr><h3 id="prompt-3-·-镜头-7-包装产品-走合成路线" tabindex="-1">Prompt 3 · 镜头 7 包装产品（走合成路线） <a class="header-anchor" href="#prompt-3-·-镜头-7-包装产品-走合成路线" aria-label="Permalink to &quot;Prompt 3 · 镜头 7 包装产品（走合成路线）&quot;">​</a></h3><p><strong>适用场景</strong> 成品包装出镜。</p><p><strong>做法</strong></p><p>按 <a href="/tools/decision-tree#a1-产品必须精确还原吗">选型决策树 A1</a>——<strong>包装袋有 logo、有印刷文字、有精确的配色，不能生成。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>链路：包装实拍（或用设计源文件做 3D 渲染）</span></span>
<span class="line"><span>      → AI 生成背景与光环境</span></span>
<span class="line"><span>      → 设计软件合成 + 加字幕</span></span></code></pre></div><p><strong>背景的 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个空的浅色木质台面，背景是柔和虚化的暖色环境，画面中央大面积留白，</span></span>
<span class="line"><span></span></span>
<span class="line"><span>食品广告摄影，暖色调，轻微胶片颗粒，</span></span>
<span class="line"><span>50mm 镜头，浅景深 f/2.8，微俯机位，</span></span>
<span class="line"><span>柔和的侧逆光从右后方打来，台面有自然的光影过渡，</span></span>
<span class="line"><span>竖版 9:16，高细节</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向：文字、水印、任何产品、任何包装、杂乱物品</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>关键词</th><th>作用</th></tr></thead><tbody><tr><td>中央大面积留白</td><td>给合成的包装留位置</td></tr><tr><td>任何产品 / 任何包装（负向）</td><td>不排除的话模型会自己放个包装袋进去，合成时要多一道去除</td></tr></tbody></table><p><strong>常见翻车点</strong></p><p>**试图让 AI 画出包装上的文字。**生成的中文必然是乱码，英文也常错。包装一律走实拍或渲染，这一步没有捷径。</p><hr><h2 id="附-·-用-gemini-直接生成视频的完整提示词" tabindex="-1">附 · 用 Gemini 直接生成视频的完整提示词 <a class="header-anchor" href="#附-·-用-gemini-直接生成视频的完整提示词" aria-label="Permalink to &quot;附 · 用 Gemini 直接生成视频的完整提示词&quot;">​</a></h2><p>上面 ③ 里的 Prompt 是<strong>给图像模型用的</strong>，关键词堆砌式。如果你要把这七个镜头直接丢给 Gemini 出视频，得换一种写法——照搬过去效果会明显打折。</p><h3 id="三个必须知道的结构差异" tabindex="-1">三个必须知道的结构差异 <a class="header-anchor" href="#三个必须知道的结构差异" aria-label="Permalink to &quot;三个必须知道的结构差异&quot;">​</a></h3><p>Gemini 的视频生成（Veo 系列）和 Midjourney 那类图像模型，提示词的吃法不一样：</p><table tabindex="0"><thead><tr><th></th><th>图像模型（前面 ③ 的写法）</th><th>Gemini / Veo</th></tr></thead><tbody><tr><td><strong>句式</strong></td><td>关键词用逗号堆叠</td><td><strong>完整的描述性句子</strong>，像在跟摄影师讲戏</td></tr><tr><td><strong>否定</strong></td><td>在正文里写「负向：文字、水印」</td><td><strong>单独填 negative prompt 字段</strong>，正文里不要出现否定词</td></tr><tr><td><strong>音频</strong></td><td>无</td><td>Veo 3 系列<strong>原生生成音效与环境音</strong>，提示词里可以直接描述声音</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">第二条最容易踩坑</p><p>在 Veo 的主提示词里写「不要有文字」「没有人物」这类否定句，<strong>反而可能把这些元素引进来</strong>——模型会注意到「文字」这个词本身。</p><p>否定内容一律填到单独的 negative prompt 输入框里，只写名词，不写「不要」。这是 Google 官方提示词指南里明确说明的用法。</p><p>下面每条我都把 negative prompt 单独列出来了，<strong>别把它粘进正文</strong>。</p></div><div class="warning custom-block"><p class="custom-block-title">具体功能以官网为准</p><p>Veo 的版本、可用时长、分辨率、是否支持音频、negative prompt 的入口位置，各渠道（Gemini App / Google AI Studio / Vertex AI）不同且更新频繁。这里给的是<strong>提示词写法</strong>，不是操作步骤。</p></div><h3 id="先看清楚-七条里有三条纯文生视频做不出来" tabindex="-1">先看清楚：七条里有三条纯文生视频做不出来 <a class="header-anchor" href="#先看清楚-七条里有三条纯文生视频做不出来" aria-label="Permalink to &quot;先看清楚：七条里有三条纯文生视频做不出来&quot;">​</a></h3><p>在你逐条粘贴之前，先知道哪些能成、哪些不能——省得白烧额度。</p><table tabindex="0"><thead><tr><th>镜头</th><th>纯文生视频可行性</th><th>说明</th></tr></thead><tbody><tr><td>1 · 切片落下</td><td>✅ 可行</td><td>简单单一动作</td></tr><tr><td>2 · 悬浮静止</td><td>✅ 可行</td><td>「静止」对模型是舒适区</td></tr><tr><td>3 · 气泡逸出</td><td>⚠️ 勉强</td><td>液体/气泡是弱项，废片率高，多生成</td></tr><tr><td>4 · 色泽转变</td><td>❌ <strong>不可行</strong></td><td>渐变过程，模型控不住，见下方替代方案</td></tr><tr><td>5 · 掰断</td><td>❌ <strong>不可行</strong></td><td>形变不可逆，必须首尾帧，见 <a href="/cases/case-03-fries-social#prompt-2-·-镜头-3-掰断-首尾帧控制">案例 03</a></td></tr><tr><td>6 · 成品掉落</td><td>✅ 可行</td><td>多物体但动作单一</td></tr><tr><td>7 · 包装出镜</td><td>❌ <strong>不可行</strong></td><td>包装有 logo 和文字，必须实拍合成</td></tr></tbody></table><p>**四条能直接生成，三条需要别的做法。**这个比例在工艺类项目里算正常——越是有精确要求的镜头，越不能交给纯文生视频。</p><hr><h3 id="镜头-1-·-原料入场-3-秒" tabindex="-1">镜头 1 · 原料入场（3 秒） <a class="header-anchor" href="#镜头-1-·-原料入场-3-秒" aria-label="Permalink to &quot;镜头 1 · 原料入场（3 秒）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一片薄薄的生土豆切片以慢动作落到拉丝不锈钢台面上，轻微弹跳后静止。</span></span>
<span class="line"><span>极特写微距镜头，浅景深，镜头保持完全静止不动。</span></span>
<span class="line"><span>强烈的侧逆光从右后方打来，勾勒出切片边缘，光线透过薄片显出半透明的质感。</span></span>
<span class="line"><span>高端食品广告摄影风格，暖金色调，背景是压暗的深色环境，画面干净。</span></span>
<span class="line"><span>细腻的胶片颗粒质感，真实照片般的写实感。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>声音：土豆片落在金属台面上一声轻脆的接触声，安静的室内环境音，没有配乐。</span></span></code></pre></div><p><strong>Negative prompt</strong>（填到单独的输入框）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>text, watermark, logo, hands, multiple slices, cluttered background, plastic look, CGI, cartoon</span></span></code></pre></div><p><strong>这条在控制什么</strong>：用慢动作 + 微距建立「郑重对待原料」的基调。侧逆光透出薄片的半透明感，是这一镜唯一的技术要求。</p><details class="details custom-block"><summary>英文版本（响应通常更稳）</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A single thin slice of raw potato falls in slow motion onto a brushed stainless steel surface, bouncing softly once before settling. Extreme close-up macro shot, shallow depth of field, camera completely static. Strong side-backlight from the rear right rims the edge of the slice, light passing through it revealing a translucent thinness. High-end food commercial cinematography, warm golden tone, dark moody background, clean composition. Fine film grain, photorealistic.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Audio: one soft crisp impact of potato on metal, quiet room tone, no music.</span></span></code></pre></div></details><hr><h3 id="镜头-2-·-负压隐喻-3-秒" tabindex="-1">镜头 2 · 负压隐喻（3 秒） <a class="header-anchor" href="#镜头-2-·-负压隐喻-3-秒" aria-label="Permalink to &quot;镜头 2 · 负压隐喻（3 秒）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一片生土豆切片静止悬浮在一片纯粹的深黑虚空中，下方没有任何支撑物，</span></span>
<span class="line"><span>周围有极细微的悬浮颗粒，同样凝固在空中一动不动，整个空间像时间被按下了暂停。</span></span>
<span class="line"><span>中景微距镜头，极浅景深，镜头极其缓慢地向前推近。</span></span>
<span class="line"><span>一道冷白色的轮廓光从右后方勾勒出切片的边缘，背景是纯粹的深黑。</span></span>
<span class="line"><span>概念科学可视化风格，冷调偏青蓝，极简，画面中只有这一个主体。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>声音：低沉的环境嗡鸣，几乎无声，营造真空般的寂静。</span></span></code></pre></div><p><strong>Negative prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>text, watermark, oil, liquid, bubbling, boiling, splashing, multiple objects, busy background, sci-fi HUD, glowing particles, lens flare</span></span></code></pre></div><p><strong>这条在控制什么</strong>：全片的概念核心。<strong>关键是「静」</strong>——一旦出现油、气泡、翻腾，负压的隐喻立刻垮掉变成普通油锅，所以 negative prompt 里把这些全排除了。「悬浮颗粒同样静止」这句比只让主体悬浮更有说服力。</p><details class="details custom-block"><summary>英文版本</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A single thin slice of raw potato hangs perfectly still, suspended in a pure black void with nothing supporting it. Tiny particles float around it, equally frozen in place, as if time itself has stopped. Medium macro shot, very shallow depth of field, camera pushes in extremely slowly. A single cold white rim light from the rear right traces the edge of the slice against the pure black background. Conceptual scientific visualization style, cool cyan-blue tone, minimalist, one subject only.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Audio: a low ambient hum, near silence, a vacuum-like stillness.</span></span></code></pre></div></details><hr><h3 id="镜头-3-·-水分汽化-4-秒-·-核心镜头" tabindex="-1">镜头 3 · 水分汽化（4 秒）· 核心镜头 <a class="header-anchor" href="#镜头-3-·-水分汽化-4-秒-·-核心镜头" aria-label="Permalink to &quot;镜头 3 · 水分汽化（4 秒）· 核心镜头&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>极致微距镜头，一片土豆切片的表面，细密的小气泡从切片内部缓慢地向外逸出，</span></span>
<span class="line"><span>气泡一颗一颗地形成、膨胀、离开表面，整个过程非常缓慢，像升格慢镜头。</span></span>
<span class="line"><span>镜头保持静止，极浅景深，只有切片表面的一小块区域是清晰的。</span></span>
<span class="line"><span>强烈的逆光从背后穿过，每一颗气泡都被光点亮，呈现出半透明的亮点，背景压暗成深色。</span></span>
<span class="line"><span>科学微距摄影风格，冷调转向暖调的过渡，真实的物理质感，细腻的胶片颗粒。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>声音：极其轻微的细密气泡声，缓慢而有节奏，没有配乐。</span></span></code></pre></div><p><strong>Negative prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>text, watermark, violent boiling, splashing oil, fast motion, large bubbles, foam, soap suds, CGI, cartoon</span></span></code></pre></div><p><strong>这条在控制什么</strong>：全片说服力的来源——<strong>看得见的脱水过程</strong>。三个要点：气泡要小而密（大气泡=沸腾=高温，与低温工艺矛盾）、要慢、要逆光点亮。</p><div class="warning custom-block"><p class="custom-block-title">这一镜废片率最高</p><p>气泡的物理行为是视频模型的弱项（和 <a href="/cases/case-01-beverage-tvc">案例 01</a> 的气泡镜头同类问题）。常见翻车：气泡凭空出现又消失、往下走、或者突然变成剧烈沸腾。</p><p>**多生成，排期留双倍时间。**如果反复不成，退一步用图像模型生成一张气泡静帧，再走图生视频，可控性会好很多。</p></div><details class="details custom-block"><summary>英文版本</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Extreme macro shot of the surface of a potato slice. Fine, tiny bubbles emerge slowly from within the slice, each one forming, expanding and releasing from the surface in extreme slow motion. The camera stays perfectly still with very shallow depth of field, only a small patch of the surface in focus. Strong backlight passes through from behind, illuminating each bubble as a translucent bright point against a darkened background. Scientific macro cinematography, cool tone shifting toward warm, realistic physical texture, fine film grain.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Audio: very faint fine bubbling, slow and rhythmic, no music.</span></span></code></pre></div></details><hr><h3 id="镜头-4-·-色泽转变-2-秒-❌-纯文生做不出来" tabindex="-1">镜头 4 · 色泽转变（2 秒）❌ 纯文生做不出来 <a class="header-anchor" href="#镜头-4-·-色泽转变-2-秒-❌-纯文生做不出来" aria-label="Permalink to &quot;镜头 4 · 色泽转变（2 秒）❌ 纯文生做不出来&quot;">​</a></h3><p><strong>为什么不行</strong>：这一镜要的是同一个物体在时间上的颜色渐变。视频模型控不住渐变的起点和终点——它会变过头、变不够、或者中途反复。</p><p><strong>替代方案（推荐）</strong>：用图像模型生成<strong>两张</strong>图——生土豆的浅白色一张、成品的金黄色一张，构图完全一致——然后走<strong>首尾帧控制</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【首尾帧模式】</span></span>
<span class="line"><span>[首帧：浅白色的土豆切片] → [尾帧：金黄色的成品切片]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>切片的颜色从浅白色缓慢地转变为温暖的金黄色，形状和位置保持完全不变，</span></span>
<span class="line"><span>镜头静止，光线保持一致。</span></span></code></pre></div><p><strong>Negative prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>shape change, movement, position shift, camera motion, text, watermark</span></span></code></pre></div><p><strong>更省事的替代方案</strong>：这一镜其实可以<strong>在剪辑阶段做</strong>——同一张静帧素材，用调色关键帧把色相从浅白推到金黄，两秒钟的镜头，五分钟就做完了，且完全可控。</p><div class="tip custom-block"><p class="custom-block-title">一个通用判断</p><p><strong>能在后期两分钟做完的效果，不要花两小时去生成。</strong></p><p>颜色变化、简单的缩放推拉、亮度渐变、叠化转场——这些交给剪辑软件比交给视频模型又快又准。视频模型的额度应该花在后期做不出来的东西上（真实的物理运动、复杂的光影变化）。</p></div><hr><h3 id="镜头-5-·-蜂窝断面-3-秒-❌-纯文生做不出来" tabindex="-1">镜头 5 · 蜂窝断面（3 秒）❌ 纯文生做不出来 <a class="header-anchor" href="#镜头-5-·-蜂窝断面-3-秒-❌-纯文生做不出来" aria-label="Permalink to &quot;镜头 5 · 蜂窝断面（3 秒）❌ 纯文生做不出来&quot;">​</a></h3><p><strong>为什么不行</strong>：掰断是不可逆形变，纯文生视频会出现「断了又愈合」「两截比原来长」。完整说明见 <a href="/cases/case-03-fries-social#prompt-2-·-镜头-3-掰断-首尾帧控制">案例 03 的首尾帧方案</a>。</p><p><strong>替代方案</strong>：先用 ③ 里的 <a href="#prompt-2-·-镜头-5-蜂窝断面-酥脆的物证">Prompt 2</a> 生成一张满意的断面静图作为<strong>尾帧</strong>，再生成一张完整薯条脆的<strong>首帧</strong>，走首尾帧模式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【首尾帧模式】</span></span>
<span class="line"><span>[首帧：完整的一片薯条脆] → [尾帧：掰成两半，断面朝向镜头]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>薯条脆被缓慢地掰成两半，断面转向镜头，</span></span>
<span class="line"><span>强烈的逆光穿过断面的孔隙形成明亮的透光点，</span></span>
<span class="line"><span>除此之外画面其余部分保持静止。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>声音：一声清脆的断裂声，干燥而清晰，随后是安静。</span></span></code></pre></div><p><strong>Negative prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>healing, reassembling, extra pieces, changing size, fast motion, camera cut, deformed fingers, text, watermark</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">尾帧决定成败</p><p>先把<strong>尾帧</strong>（断面那张）调到满意，再回头做首帧。断面的孔隙结构是这一镜的全部价值，首帧只是个起点。</p><p>生成断面静图时记得排除 <code>regular holes, honeycomb pattern, hexagonal</code> —— 模型对「蜂窝」的默认理解是六边形蜂巢，那是蜜蜂做的，不是油炸做的。</p></div><hr><h3 id="镜头-6-·-成品掉落-3-秒" tabindex="-1">镜头 6 · 成品掉落（3 秒） <a class="header-anchor" href="#镜头-6-·-成品掉落-3-秒" aria-label="Permalink to &quot;镜头 6 · 成品掉落（3 秒）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一堆金黄色的薯条脆片从画面上方缓缓落下，堆叠在浅色木质台面上，</span></span>
<span class="line"><span>片与片之间自然地叠压、轻微滑动后静止，每一片的形状和色泽都略有不同，</span></span>
<span class="line"><span>边缘不规则，表面有深浅不一的金黄色斑点。</span></span>
<span class="line"><span>特写镜头，浅景深，慢动作，镜头保持静止。</span></span>
<span class="line"><span>温暖的侧逆光从右后方打来，片与片的边缘被光勾出明亮的轮廓，背景虚化压暗。</span></span>
<span class="line"><span>高端食品广告摄影，暖金色调，细腻的胶片颗粒，真实的食物质感。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>声音：薯条脆片相互碰撞的清脆声响，干燥、轻盈、有层次，没有配乐。</span></span></code></pre></div><p><strong>Negative prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>text, watermark, packaging, uniform shapes, identical pieces, perfect symmetry, plastic look, wax look, CGI, soggy, oily surface</span></span></code></pre></div><p><strong>这条在控制什么</strong>：食欲感的落点。<strong>关键是「每一片都略有不同」「边缘不规则」「斑点深浅不一」</strong>——这是 <a href="/cases/case-03-fries-social">案例 03</a> 得出的核心结论：完美即虚假。negative prompt 里排除 <code>uniform shapes, identical pieces</code> 就是同一个道理。</p><details class="details custom-block"><summary>英文版本</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A pile of golden potato crisps falls gently from above onto a light wooden surface, the pieces overlapping and sliding slightly before settling. Each piece has a slightly different shape and colour, with irregular edges and uneven golden-brown speckles across the surface. Close-up shot, shallow depth of field, slow motion, camera static. Warm side-backlight from the rear right rims the edges of the pieces with bright outlines, background darkened and blurred. High-end food commercial cinematography, warm golden tone, fine film grain, realistic food texture.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Audio: crisp dry clatter of the pieces landing against each other, light and layered, no music.</span></span></code></pre></div></details><hr><h3 id="镜头-7-·-包装出镜-2-秒-❌-不要生成" tabindex="-1">镜头 7 · 包装出镜（2 秒）❌ 不要生成 <a class="header-anchor" href="#镜头-7-·-包装出镜-2-秒-❌-不要生成" aria-label="Permalink to &quot;镜头 7 · 包装出镜（2 秒）❌ 不要生成&quot;">​</a></h3><p>包装袋有 logo、有印刷文字、有精确的品牌配色。<strong>生成模型画不对，也不该让它画。</strong></p><p><strong>做法</strong>：用 ③ 的 <a href="#prompt-3-·-镜头-7-包装产品-走合成路线">Prompt 3</a> 生成一个<strong>空台面背景</strong>，包装用实拍或设计源文件渲染，最后在设计软件里合成 + 加字幕。</p><p>如果这一镜需要轻微的动态（比如缓慢推近），有两个办法：</p><ol><li><strong>在剪辑软件里做</strong>——静态合成图 + 关键帧缩放，两分钟搞定，完全可控（同镜头 4 的判断）</li><li>让 Gemini 只生成<strong>空背景的动态</strong>（光影缓慢变化），再把包装合成上去——但这需要跟踪，通常不划算</li></ol><hr><h3 id="一个建议的执行顺序" tabindex="-1">一个建议的执行顺序 <a class="header-anchor" href="#一个建议的执行顺序" aria-label="Permalink to &quot;一个建议的执行顺序&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">先跑通全片，再抠单镜</p><ol><li><strong>先把能生成的四条（1、2、3、6）各出一版</strong>，拼起来看整体调性对不对</li><li>调性对了，再回头挑质量不达标的重做</li><li>镜头 4、5、7 走各自的替代方案</li><li>全部达标后，关键镜头（2、3）多生成 2–3 个备选留给剪辑</li></ol><p>不要在镜头 1 上死磕到完美再做镜头 2——很容易出现「每个镜头都好看，串起来不像一支片子」。这条在 <a href="/method/workflow-sop#_5-生成">完整链路 SOP</a> 里说过，这里再强调一次，因为它是最常被违反的一条。</p></div><h3 id="跨镜头一致性怎么保" tabindex="-1">跨镜头一致性怎么保 <a class="header-anchor" href="#跨镜头一致性怎么保" aria-label="Permalink to &quot;跨镜头一致性怎么保&quot;">​</a></h3><p>这七条里，我把风格描述<strong>分散写进了每条的正文</strong>（暖金色调、细腻胶片颗粒、浅景深、侧逆光），而不是像 ③ 那样抽成一个独立的「风格包」段落——因为 Veo 吃的是连贯句子，硬塞一段关键词会破坏句式。</p><p>代价是一致性更难保。三个对策：</p><ol><li><strong>风格句子逐字复制。</strong>「高端食品广告摄影，暖金色调，细腻的胶片颗粒，真实的食物质感」这一句在每条里保持完全一致，不要换同义词。</li><li><strong>镜头 2 是例外</strong>——它是冷调概念镜头，色调本来就该和其余不同，靠镜头 4 完成冷暖过渡。</li><li>**兜底靠调色。**AI 素材的色温漂移是常态，全片套同一个 LUT 能救回大部分。见 <a href="/tools/landscape#_5-剪辑与后期">工具地图</a>。</li></ol><hr><h2 id="_4-可复用套路" tabindex="-1">④ 可复用套路 <a class="header-anchor" href="#_4-可复用套路" aria-label="Permalink to &quot;④ 可复用套路&quot;">​</a></h2><ol><li><p>**AI 最大的优势是拍得到拍不到的东西。**工艺内部、微观结构、抽象原理、时间尺度——这些实拍要么不可能要么极贵，AI 反而擅长。**技术类、工艺类内容是 AI 广告目前性价比最高的场景之一。**这一条和 <a href="/cases/case-03-fries-social">案例 03</a> 正好互补：拍真实食物 AI 有短板，拍不存在的画面 AI 有长板。</p></li><li><p><strong>卖工艺就展示做法，不要展示好处。</strong>「更健康」是结论——违规且不可信；「我们在负压下低温炸了它」是事实——合规、可展示，且消费者会自己得出结论。**你替他下的结论他不信，他自己下的结论他才信。**这条能迁移到所有技术卖点类项目。</p></li><li><p>**做工艺类项目，第一件事是把技术搞懂。**搞不懂只能写空话或写错话。**要到技术方的资料，看懂了再动手。**这一步省不掉。</p></li><li><p>**视觉隐喻必须能追溯到技术事实。**判断标准：这个画面对应的原理，能不能在技术资料里找到出处？找不到就别画——那叫伪科学包装。</p></li><li><p>**工期里要留出核查与审校的时间，并计入报价。**感官类项目不需要，技术主张类项目必须有。这个案例四天里有一整天不产出画面。不预留，你就是在免费做法务工作。</p></li><li><p>**对比结构要慎用。**直接对比同类产品容易构成贬低，是法律风险不是创意选择。<strong>只展示自己，让对比发生在观众脑子里。</strong></p></li><li><p>**「知道」和「能说」是两回事。**有科学依据的事实，在广告语境下也可能因为构成健康暗示而不能说。这个分寸感是做食品广告的基本功。</p></li><li><p>**能在后期两分钟做完的效果，不要花两小时去生成。**颜色渐变、缩放推拉、亮度变化、叠化转场——交给剪辑软件又快又准且完全可控。视频模型的额度应该花在后期做不出来的东西上（真实的物理运动、复杂光影）。这个案例的镜头 4 就是典型：与其反复生成色泽转变，不如一张静帧加两个调色关键帧。</p></li><li><p>**动手前先分类哪些镜头能纯生成、哪些不能。**这个案例七个镜头里有三个纯文生视频做不出来（渐变、形变、带文字的包装）。**先分类再开工，能省掉大量白烧的额度。**判断依据：涉及不可逆形变、精确渐变、品牌文字的，都不要指望纯文生视频。</p></li></ol><h2 id="如果重做一次" tabindex="-1">如果重做一次 <a class="header-anchor" href="#如果重做一次" aria-label="Permalink to &quot;如果重做一次&quot;">​</a></h2><p><strong>镜头 2（悬浮）和镜头 3（气泡）的顺序应该对调。</strong></p><p>现在的顺序是先抽象（悬浮的负压隐喻）再具体（气泡逸出）。实际观看时，观众在第 3 秒看到一个悬浮的土豆片，会有几秒钟的困惑——不知道在看什么。</p><p>如果先给具体的气泡逸出（看得懂：在脱水），再给悬浮的空间感（此时已有上下文：哦，是在一个特殊环境里），理解成本会低很多。</p><p>**教训：概念镜头不要放在最前面。**先给观众一个能看懂的画面建立上下文，再上抽象表达。这一条和 <a href="/cases/case-01-beverage-tvc">案例 01</a>、<a href="/cases/case-03-fries-social">案例 03</a> 的「砍掉铺垫」不冲突——铺垫是无信息量的过渡，而上下文是理解的前提，两者要分清。</p><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><ul><li><strong>动手之前那一步：这个产品该拍什么类型的片子</strong> → <a href="/cases/case-04-fries-crisp-formats">片型可行性分析</a></li><li>同为薯条、但卖感官不卖工艺 → <a href="/cases/case-03-fries-social">案例 03 · 快餐薯条社媒短视频</a></li><li>包装/产品必须精确时的链路选择 → <a href="/tools/decision-tree">选型决策树</a></li><li>文案的合规检查方法 → <a href="/prompts/copywriting#一个通用技巧-让-ai-当批评者">广告文案与口播</a></li></ul>`,163)])])}const u=a(p,[["render",o]]);export{g as __pageData,u as default};
